//youtube.com",brand_zalo:"https://zalo.me/0901234567",brand_tiktok:"https://tiktok.com",page_home_enabled:"1",page_album_enabled:"1",page_about_enabled:"1",page_contact_enabled:"1",album_header_label:"Bộ Sưu Tập Nghệ Thuật",album_header_title:"Khoảnh Khắc Của Bé",album_header_title_highlight:"Kể Bằng Hình Ảnh",album_header_desc:"Mỗi bức ảnh là một tác phẩm được chăm chút tỉ mỉ, giúp bố mẹ lưu lại trọn vẹn những ký ức đầu đời thiêng liêng nhất của con yêu.",about_header_label:"Lời Ngỏ Từ Trái Tim",about_story_title:"Nhiếp ảnh là cách mình lưu giữ linh hồn của khoảnh khắc.",about_story_p1:"Chào bạn, mình là Min — một người say mê nhiếp ảnh và cái đẹp từ những điều dung dị nhất. Mình hiện đang sống và làm việc tại Bình Dương, chuyên về ảnh em bé, chân dung ngoài trời (ngoại cảnh).",about_story_p2:"Đối với mình, mỗi buổi chụp không đơn thuần là một buổi làm việc, mà là cuộc gặp gỡ, trò chuyện và cùng tạo nên những kỷ niệm đẹp qua từng bức ảnh.",about_image:"https://images.unsplash.com/photo-1555252333-9f8e92e65df9?w=900&q=85",about_quote_text:"Mỗi em bé là một thiên thần nhỏ, mỗi nụ cười là một câu chuyện vô giá được lưu giữ trọn vẹn qua thời gian.",about_quote_author:"",about_quote_color:"#1f2937",about_quote_author_color:"#E06738",home_intro_image:"https://images.unsplash.com/photo-1555252333-9f8e92e65df9?w=900&q=85",home_intro_label:"Giới thiệu về QA Stories",home_intro_title:"Nghệ Thuật Lưu Giữ",home_intro_title_highlight:"Những Khoảnh Khắc Đầu Đời",home_intro_p1:"Tại QA Stories, chúng tôi hiểu rằng thời thơ ấu của con trôi qua rất nhanh. Từng ngón tay bé xíu, từng cái ngáp ngủ dễ thương hay nụ cười đầu tiên đều là những báu vật vô giá không thể lặp lại.",home_intro_p2:"Với hơn 5 năm kinh nghiệm chuyên sâu trong lĩnh vực nhiếp ảnh trẻ em, chúng tôi tạo dựng một không gian an toàn, ấm áp và phong cách nghệ thuật tinh tế để mỗi bức ảnh không chỉ đẹp mà còn đong đầy cảm xúc yêu thương.",home_intro_features:JSON.stringify(["Trang phục nhập khẩu mềm mịn cho da bé","Phòng chụp tiệt trùng UV và nhiệt độ lý tưởng","Nhiếp ảnh gia chuyên môn cao & yêu trẻ","Đa dạng concept từ tối giản đến sang trọng"]),seo_title:"QA Stories - Studio Chụp Ảnh Bé & Gia Đình Chuyên Nghiệp",seo_description:"Studio chụp ảnh sơ sinh newborn, thôi nôi, 100 ngày tuổi và gia đình uy tín với phong cách nghệ thuật, ánh sáng tự nhiên.",quick_access_enabled:"1",quick_access_items:JSON.stringify([{id:"qa-1",label:"Bộ Sưu Tập Concept",to:"/album",icon:"Images",is_active:!0},{id:"qa-2",label:"Đặt Lịch Chụp Ảnh",to:"/contact",icon:"Calendar",is_active:!0},{id:"qa-3",label:"Liên Hệ & Tư Vấn",to:"/contact",icon:"PhoneCall",is_active:!0}])},Rg=w.createContext(null);function vk({children:e}){const[t,n]=w.useState(yk),[r,i]=w.useState(!0),s=async()=>{try{const a=await Os.get("/settings");a.success&&a.data&&n(l=>({...l,...a.data}))}catch(a){console.warn("Sử dụng cấu hình mặc định (API settings không khả dụng):",a.message)}finally{i(!1)}};w.useEffect(()=>{s()},[]);const o=()=>s();return g.jsx(Rg.Provider,{value:{settings:t,loading:r,refreshSettings:o},children:e})}function ao(){const e=w.useContext(Rg);if(!e)throw new Error("useSettings must be used within a SettingsProvider");return e}const xk=[{path:"/",label:"Trang Chủ"},{path:"/album",label:"Bộ Sưu Tập"},{path:"/about",label:"Giới Thiệu"},{path:"/contact",label:"Liên Hệ & Đặt Lịch"}];function wk(){const[e,t]=w.useState(!1),[n,r]=w.useState(!1),i=St(),{settings:s}=ao();w.useEffect(()=>{const c=()=>r(window.scrollY>40);return window.addEventListener("scroll",c,{passive:!0}),()=>window.removeEventListener("scroll",c)},[]),w.useEffect(()=>{t(!1)},[i]);const o=i.pathname==="/",a=c=>s?c==="/"?s.page_home_enabled!=="0"&&s.page_home_enabled!==!1&&s.page_home_enabled!==0:c==="/album"?s.page_album_enabled!=="0"&&s.page_album_enabled!==!1&&s.page_album_enabled!==0:c==="/about"?s.page_about_enabled!=="0"&&s.page_about_enabled!==!1&&s.page_about_enabled!==0:c==="/contact"?s.page_contact_enabled!=="0"&&s.page_contact_enabled!==!1&&s.pa